# ! [doc = " A module for working with processes."] # ! [doc = ""] # ! [doc = " This module is mostly concerned with spawning and interacting with child"] # ! [doc = " processes, but it also provides [`abort`] and [`exit`] for terminating the"] # ! [doc = " current process."] # ! [doc = ""] # ! [doc = " # Spawning a process"] # ! [doc = ""] # ! [doc = " The [`Command`] struct is used to configure and spawn processes:"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " use std::process::Command;"] # ! [doc = ""] # ! [doc = " let output = Command::new(\"echo\")"] # ! [doc = "     .arg(\"Hello world\")"] # ! [doc = "     .output()"] # ! [doc = "     .expect(\"Failed to execute command\");"] # ! [doc = ""] # ! [doc = " assert_eq!(b\"Hello world\\n\", output.stdout.as_slice());"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Several methods on [`Command`], such as [`spawn`] or [`output`], can be used"] # ! [doc = " to spawn a process. In particular, [`output`] spawns the child process and"] # ! [doc = " waits until the process terminates, while [`spawn`] will return a [`Child`]"] # ! [doc = " that represents the spawned child process."] # ! [doc = ""] # ! [doc = " # Handling I/O"] # ! [doc = ""] # ! [doc = " The [`stdout`], [`stdin`], and [`stderr`] of a child process can be"] # ! [doc = " configured by passing an [`Stdio`] to the corresponding method on"] # ! [doc = " [`Command`]. Once spawned, they can be accessed from the [`Child`]. For"] # ! [doc = " example, piping output from one command into another command can be done"] # ! [doc = " like so:"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " use std::process::{Command, Stdio};"] # ! [doc = ""] # ! [doc = " // stdout must be configured with `Stdio::piped` in order to use"] # ! [doc = " // `echo_child.stdout`"] # ! [doc = " let echo_child = Command::new(\"echo\")"] # ! [doc = "     .arg(\"Oh no, a tpyo!\")"] # ! [doc = "     .stdout(Stdio::piped())"] # ! [doc = "     .spawn()"] # ! [doc = "     .expect(\"Failed to start echo process\");"] # ! [doc = ""] # ! [doc = " // Note that `echo_child` is moved here, but we won't be needing"] # ! [doc = " // `echo_child` anymore"] # ! [doc = " let echo_out = echo_child.stdout.expect(\"Failed to open echo stdout\");"] # ! [doc = ""] # ! [doc = " let mut sed_child = Command::new(\"sed\")"] # ! [doc = "     .arg(\"s/tpyo/typo/\")"] # ! [doc = "     .stdin(Stdio::from(echo_out))"] # ! [doc = "     .stdout(Stdio::piped())"] # ! [doc = "     .spawn()"] # ! [doc = "     .expect(\"Failed to start sed process\");"] # ! [doc = ""] # ! [doc = " let output = sed_child.wait_with_output().expect(\"Failed to wait on sed\");"] # ! [doc = " assert_eq!(b\"Oh no, a typo!\\n\", output.stdout.as_slice());"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Note that [`ChildStderr`] and [`ChildStdout`] implement [`Read`] and"] # ! [doc = " [`ChildStdin`] implements [`Write`]:"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " use std::process::{Command, Stdio};"] # ! [doc = " use std::io::Write;"] # ! [doc = ""] # ! [doc = " let mut child = Command::new(\"/bin/cat\")"] # ! [doc = "     .stdin(Stdio::piped())"] # ! [doc = "     .stdout(Stdio::piped())"] # ! [doc = "     .spawn()"] # ! [doc = "     .expect(\"failed to execute child\");"] # ! [doc = ""] # ! [doc = " // If the child process fills its stdout buffer, it may end up"] # ! [doc = " // waiting until the parent reads the stdout, and not be able to"] # ! [doc = " // read stdin in the meantime, causing a deadlock."] # ! [doc = " // Writing from another thread ensures that stdout is being read"] # ! [doc = " // at the same time, avoiding the problem."] # ! [doc = " let mut stdin = child.stdin.take().expect(\"failed to get stdin\");"] # ! [doc = " std::thread::spawn(move || {"] # ! [doc = "     stdin.write_all(b\"test\").expect(\"failed to write to stdin\");"] # ! [doc = " });"] # ! [doc = ""] # ! [doc = " let output = child"] # ! [doc = "     .wait_with_output()"] # ! [doc = "     .expect(\"failed to wait on child\");"] # ! [doc = ""] # ! [doc = " assert_eq!(b\"test\", output.stdout.as_slice());"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Windows argument splitting"] # ! [doc = ""] # ! [doc = " On Unix systems arguments are passed to a new process as an array of strings,"] # ! [doc = " but on Windows arguments are passed as a single commandline string and it is"] # ! [doc = " up to the child process to parse it into an array. Therefore the parent and"] # ! [doc = " child processes must agree on how the commandline string is encoded."] # ! [doc = ""] # ! [doc = " Most programs use the standard C run-time `argv`, which in practice results"] # ! [doc = " in consistent argument handling. However, some programs have their own way of"] # ! [doc = " parsing the commandline string. In these cases using [`arg`] or [`args`] may"] # ! [doc = " result in the child process seeing a different array of arguments than the"] # ! [doc = " parent process intended."] # ! [doc = ""] # ! [doc = " Two ways of mitigating this are:"] # ! [doc = ""] # ! [doc = " * Validate untrusted input so that only a safe subset is allowed."] # ! [doc = " * Use [`raw_arg`] to build a custom commandline. This bypasses the escaping"] # ! [doc = "   rules used by [`arg`] so should be used with due caution."] # ! [doc = ""] # ! [doc = " `cmd.exe` and `.bat` files use non-standard argument parsing and are especially"] # ! [doc = " vulnerable to malicious input as they may be used to run arbitrary shell"] # ! [doc = " commands. Untrusted arguments should be restricted as much as possible."] # ! [doc = " For examples on handling this see [`raw_arg`]."] # ! [doc = ""] # ! [doc = " ### Batch file special handling"] # ! [doc = ""] # ! [doc = " On Windows, `Command` uses the Windows API function [`CreateProcessW`] to"] # ! [doc = " spawn new processes. An undocumented feature of this function is that"] # ! [doc = " when given a `.bat` file as the application to run, it will automatically"] # ! [doc = " convert that into running `cmd.exe /c` with the batch file as the next argument."] # ! [doc = ""] # ! [doc = " For historical reasons Rust currently preserves this behavior when using"] # ! [doc = " [`Command::new`], and escapes the arguments according to `cmd.exe` rules."] # ! [doc = " Due to the complexity of `cmd.exe` argument handling, it might not be"] # ! [doc = " possible to safely escape some special characters, and using them will result"] # ! [doc = " in an error being returned at process spawn. The set of unescapeable"] # ! [doc = " special characters might change between releases."] # ! [doc = ""] # ! [doc = " Also note that running batch scripts in this way may be removed in the"] # ! [doc = " future and so should not be relied upon."] # ! [doc = ""] # ! [doc = " [`spawn`]: Command::spawn"] # ! [doc = " [`output`]: Command::output"] # ! [doc = ""] # ! [doc = " [`stdout`]: Command::stdout"] # ! [doc = " [`stdin`]: Command::stdin"] # ! [doc = " [`stderr`]: Command::stderr"] # ! [doc = ""] # ! [doc = " [`Write`]: io::Write"] # ! [doc = " [`Read`]: io::Read"] # ! [doc = ""] # ! [doc = " [`arg`]: Command::arg"] # ! [doc = " [`args`]: Command::args"] # ! [doc = " [`raw_arg`]: crate::os::windows::process::CommandExt::raw_arg"] # ! [doc = ""] # ! [doc = " [`CreateProcessW`]: https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/nf-processthreadsapi-createprocessw"] # ! [stable (feature = "process" , since = "1.0.0")] # ! [deny (unsafe_op_in_unsafe_fn)] use split_decls_genesis :: ourprelude :: * ; #[cfg (all (test , not (any (target_os = "emscripten" , target_os = "wasi" , target_env = "sgx" , target_os = "xous" , target_os = "trusty" ,))))] mod tests ; use crate :: convert :: Infallible ; use crate :: ffi :: OsStr ; use crate :: io :: prelude :: * ; use crate :: io :: { self , BorrowedCursor , IoSlice , IoSliceMut } ; use crate :: num :: NonZero ; use crate :: path :: Path ; use crate :: sys :: pipe :: { AnonPipe , read2 } ; use crate :: sys :: process as imp ; use crate :: sys_common :: { AsInner , AsInnerMut , FromInner , IntoInner } ; use crate :: { fmt , fs , str } ; #[doc = " Representation of a running or exited child process."] #[doc = ""] #[doc = " This structure is used to represent and manage child processes. A child"] #[doc = " process is created via the [`Command`] struct, which configures the"] #[doc = " spawning process and can itself be constructed using a builder-style"] #[doc = " interface."] #[doc = ""] #[doc = " There is no implementation of [`Drop`] for child processes,"] #[doc = " so if you do not ensure the `Child` has exited then it will continue to"] #[doc = " run, even after the `Child` handle to the child process has gone out of"] #[doc = " scope."] #[doc = ""] #[doc = " Calling [`wait`] (or other functions that wrap around it) will make"] #[doc = " the parent process wait until the child has actually exited before"] #[doc = " continuing."] #[doc = ""] #[doc = " # Warning"] #[doc = ""] #[doc = " On some systems, calling [`wait`] or similar is necessary for the OS to"] #[doc = " release resources. A process that terminated but has not been waited on is"] #[doc = " still around as a \"zombie\". Leaving too many zombies around may exhaust"] #[doc = " global resources (for example process IDs)."] #[doc = ""] #[doc = " The standard library does *not* automatically wait on child processes (not"] #[doc = " even if the `Child` is dropped), it is up to the application developer to do"] #[doc = " so. As a consequence, dropping `Child` handles without waiting on them first"] #[doc = " is not recommended in long-running applications."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```should_panic"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut child = Command::new(\"/bin/cat\")"] #[doc = "     .arg(\"file.txt\")"] #[doc = "     .spawn()"] #[doc = "     .expect(\"failed to execute child\");"] #[doc = ""] #[doc = " let ecode = child.wait().expect(\"failed to wait on child\");"] #[doc = ""] #[doc = " assert!(ecode.success());"] #[doc = " ```"] #[doc = ""] #[doc = " [`wait`]: Child::wait"] #[stable (feature = "process" , since = "1.0.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "Child")] pub struct Child { pub (crate) handle : imp :: Process , #[doc = " The handle for writing to the child's standard input (stdin), if it"] #[doc = " has been captured. You might find it helpful to do"] #[doc = ""] #[doc = " ```ignore (incomplete)"] #[doc = " let stdin = child.stdin.take().expect(\"handle present\");"] #[doc = " ```"] #[doc = ""] #[doc = " to avoid partially moving the `child` and thus blocking yourself from calling"] #[doc = " functions on `child` while using `stdin`."] #[stable (feature = "process" , since = "1.0.0")] pub stdin : Option < ChildStdin > , #[doc = " The handle for reading from the child's standard output (stdout), if it"] #[doc = " has been captured. You might find it helpful to do"] #[doc = ""] #[doc = " ```ignore (incomplete)"] #[doc = " let stdout = child.stdout.take().expect(\"handle present\");"] #[doc = " ```"] #[doc = ""] #[doc = " to avoid partially moving the `child` and thus blocking yourself from calling"] #[doc = " functions on `child` while using `stdout`."] #[stable (feature = "process" , since = "1.0.0")] pub stdout : Option < ChildStdout > , #[doc = " The handle for reading from the child's standard error (stderr), if it"] #[doc = " has been captured. You might find it helpful to do"] #[doc = ""] #[doc = " ```ignore (incomplete)"] #[doc = " let stderr = child.stderr.take().expect(\"handle present\");"] #[doc = " ```"] #[doc = ""] #[doc = " to avoid partially moving the `child` and thus blocking yourself from calling"] #[doc = " functions on `child` while using `stderr`."] #[stable (feature = "process" , since = "1.0.0")] pub stderr : Option < ChildStderr > , } #[doc = " Allows extension traits within `std`."] #[unstable (feature = "sealed" , issue = "none")] impl crate :: sealed :: Sealed for Child { } impl AsInner < imp :: Process > for Child { #[inline] fn as_inner (& self) -> & imp :: Process { & self . handle } } impl FromInner < (imp :: Process , imp :: StdioPipes) > for Child { fn from_inner ((handle , io) : (imp :: Process , imp :: StdioPipes)) -> Child { Child { handle , stdin : io . stdin . map (ChildStdin :: from_inner) , stdout : io . stdout . map (ChildStdout :: from_inner) , stderr : io . stderr . map (ChildStderr :: from_inner) , } } } impl IntoInner < imp :: Process > for Child { fn into_inner (self) -> imp :: Process { self . handle } } #[stable (feature = "std_debug" , since = "1.16.0")] impl fmt :: Debug for Child { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("Child") . field ("stdin" , & self . stdin) . field ("stdout" , & self . stdout) . field ("stderr" , & self . stderr) . finish_non_exhaustive () } } #[doc = " A handle to a child process's standard input (stdin)."] #[doc = ""] #[doc = " This struct is used in the [`stdin`] field on [`Child`]."] #[doc = ""] #[doc = " When an instance of `ChildStdin` is [dropped], the `ChildStdin`'s underlying"] #[doc = " file handle will be closed. If the child process was blocked on input prior"] #[doc = " to being dropped, it will become unblocked after dropping."] #[doc = ""] #[doc = " [`stdin`]: Child::stdin"] #[doc = " [dropped]: Drop"] #[stable (feature = "process" , since = "1.0.0")] pub struct ChildStdin { inner : AnonPipe , } #[stable (feature = "process" , since = "1.0.0")] impl Write for ChildStdin { fn write (& mut self , buf : & [u8]) -> io :: Result < usize > { (& * self) . write (buf) } fn write_vectored (& mut self , bufs : & [IoSlice < '_ >]) -> io :: Result < usize > { (& * self) . write_vectored (bufs) } fn is_write_vectored (& self) -> bool { io :: Write :: is_write_vectored (& & * self) } #[inline] fn flush (& mut self) -> io :: Result < () > { (& * self) . flush () } } #[stable (feature = "write_mt" , since = "1.48.0")] impl Write for & ChildStdin { fn write (& mut self , buf : & [u8]) -> io :: Result < usize > { self . inner . write (buf) } fn write_vectored (& mut self , bufs : & [IoSlice < '_ >]) -> io :: Result < usize > { self . inner . write_vectored (bufs) } fn is_write_vectored (& self) -> bool { self . inner . is_write_vectored () } #[inline] fn flush (& mut self) -> io :: Result < () > { Ok (()) } } impl AsInner < AnonPipe > for ChildStdin { #[inline] fn as_inner (& self) -> & AnonPipe { & self . inner } } impl IntoInner < AnonPipe > for ChildStdin { fn into_inner (self) -> AnonPipe { self . inner } } impl FromInner < AnonPipe > for ChildStdin { fn from_inner (pipe : AnonPipe) -> ChildStdin { ChildStdin { inner : pipe } } } #[stable (feature = "std_debug" , since = "1.16.0")] impl fmt :: Debug for ChildStdin { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("ChildStdin") . finish_non_exhaustive () } } #[doc = " A handle to a child process's standard output (stdout)."] #[doc = ""] #[doc = " This struct is used in the [`stdout`] field on [`Child`]."] #[doc = ""] #[doc = " When an instance of `ChildStdout` is [dropped], the `ChildStdout`'s"] #[doc = " underlying file handle will be closed."] #[doc = ""] #[doc = " [`stdout`]: Child::stdout"] #[doc = " [dropped]: Drop"] #[stable (feature = "process" , since = "1.0.0")] pub struct ChildStdout { inner : AnonPipe , } #[stable (feature = "process" , since = "1.0.0")] impl Read for ChildStdout { fn read (& mut self , buf : & mut [u8]) -> io :: Result < usize > { self . inner . read (buf) } fn read_buf (& mut self , buf : BorrowedCursor < '_ >) -> io :: Result < () > { self . inner . read_buf (buf) } fn read_vectored (& mut self , bufs : & mut [IoSliceMut < '_ >]) -> io :: Result < usize > { self . inner . read_vectored (bufs) } #[inline] fn is_read_vectored (& self) -> bool { self . inner . is_read_vectored () } fn read_to_end (& mut self , buf : & mut Vec < u8 >) -> io :: Result < usize > { self . inner . read_to_end (buf) } } impl AsInner < AnonPipe > for ChildStdout { #[inline] fn as_inner (& self) -> & AnonPipe { & self . inner } } impl IntoInner < AnonPipe > for ChildStdout { fn into_inner (self) -> AnonPipe { self . inner } } impl FromInner < AnonPipe > for ChildStdout { fn from_inner (pipe : AnonPipe) -> ChildStdout { ChildStdout { inner : pipe } } } #[stable (feature = "std_debug" , since = "1.16.0")] impl fmt :: Debug for ChildStdout { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("ChildStdout") . finish_non_exhaustive () } } #[doc = " A handle to a child process's stderr."] #[doc = ""] #[doc = " This struct is used in the [`stderr`] field on [`Child`]."] #[doc = ""] #[doc = " When an instance of `ChildStderr` is [dropped], the `ChildStderr`'s"] #[doc = " underlying file handle will be closed."] #[doc = ""] #[doc = " [`stderr`]: Child::stderr"] #[doc = " [dropped]: Drop"] #[stable (feature = "process" , since = "1.0.0")] pub struct ChildStderr { inner : AnonPipe , } #[stable (feature = "process" , since = "1.0.0")] impl Read for ChildStderr { fn read (& mut self , buf : & mut [u8]) -> io :: Result < usize > { self . inner . read (buf) } fn read_buf (& mut self , buf : BorrowedCursor < '_ >) -> io :: Result < () > { self . inner . read_buf (buf) } fn read_vectored (& mut self , bufs : & mut [IoSliceMut < '_ >]) -> io :: Result < usize > { self . inner . read_vectored (bufs) } #[inline] fn is_read_vectored (& self) -> bool { self . inner . is_read_vectored () } fn read_to_end (& mut self , buf : & mut Vec < u8 >) -> io :: Result < usize > { self . inner . read_to_end (buf) } } impl AsInner < AnonPipe > for ChildStderr { #[inline] fn as_inner (& self) -> & AnonPipe { & self . inner } } impl IntoInner < AnonPipe > for ChildStderr { fn into_inner (self) -> AnonPipe { self . inner } } impl FromInner < AnonPipe > for ChildStderr { fn from_inner (pipe : AnonPipe) -> ChildStderr { ChildStderr { inner : pipe } } } #[stable (feature = "std_debug" , since = "1.16.0")] impl fmt :: Debug for ChildStderr { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("ChildStderr") . finish_non_exhaustive () } } #[doc = " A process builder, providing fine-grained control"] #[doc = " over how a new process should be spawned."] #[doc = ""] #[doc = " A default configuration can be"] #[doc = " generated using `Command::new(program)`, where `program` gives a path to the"] #[doc = " program to be executed. Additional builder methods allow the configuration"] #[doc = " to be changed (for example, by adding arguments) prior to spawning:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let output = if cfg!(target_os = \"windows\") {"] #[doc = "     Command::new(\"cmd\")"] #[doc = "         .args([\"/C\", \"echo hello\"])"] #[doc = "         .output()"] #[doc = "         .expect(\"failed to execute process\")"] #[doc = " } else {"] #[doc = "     Command::new(\"sh\")"] #[doc = "         .arg(\"-c\")"] #[doc = "         .arg(\"echo hello\")"] #[doc = "         .output()"] #[doc = "         .expect(\"failed to execute process\")"] #[doc = " };"] #[doc = ""] #[doc = " let hello = output.stdout;"] #[doc = " ```"] #[doc = ""] #[doc = " `Command` can be reused to spawn multiple processes. The builder methods"] #[doc = " change the command without needing to immediately spawn the process."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut echo_hello = Command::new(\"sh\");"] #[doc = " echo_hello.arg(\"-c\").arg(\"echo hello\");"] #[doc = " let hello_1 = echo_hello.output().expect(\"failed to execute process\");"] #[doc = " let hello_2 = echo_hello.output().expect(\"failed to execute process\");"] #[doc = " ```"] #[doc = ""] #[doc = " Similarly, you can call builder methods after spawning a process and then"] #[doc = " spawn a new process with the modified settings."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut list_dir = Command::new(\"ls\");"] #[doc = ""] #[doc = " // Execute `ls` in the current directory of the program."] #[doc = " list_dir.status().expect(\"process failed to execute\");"] #[doc = ""] #[doc = " println!();"] #[doc = ""] #[doc = " // Change `ls` to execute in the root directory."] #[doc = " list_dir.current_dir(\"/\");"] #[doc = ""] #[doc = " // And then execute `ls` again but in the root directory."] #[doc = " list_dir.status().expect(\"process failed to execute\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "Command")] pub struct Command { inner : imp :: Command , } #[doc = " Allows extension traits within `std`."] #[unstable (feature = "sealed" , issue = "none")] impl crate :: sealed :: Sealed for Command { } impl Command { #[doc = " Constructs a new `Command` for launching the program at"] #[doc = " path `program`, with the following default configuration:"] #[doc = ""] #[doc = " * No arguments to the program"] #[doc = " * Inherit the current process's environment"] #[doc = " * Inherit the current process's working directory"] #[doc = " * Inherit stdin/stdout/stderr for [`spawn`] or [`status`], but create pipes for [`output`]"] #[doc = ""] #[doc = " [`spawn`]: Self::spawn"] #[doc = " [`status`]: Self::status"] #[doc = " [`output`]: Self::output"] #[doc = ""] #[doc = " Builder methods are provided to change these defaults and"] #[doc = " otherwise configure the process."] #[doc = ""] #[doc = " If `program` is not an absolute path, the `PATH` will be searched in"] #[doc = " an OS-defined way."] #[doc = ""] #[doc = " The search path to be used may be controlled by setting the"] #[doc = " `PATH` environment variable on the Command,"] #[doc = " but this has some implementation limitations on Windows"] #[doc = " (see issue #37519)."] #[doc = ""] #[doc = " # Platform-specific behavior"] #[doc = ""] #[doc = " Note on Windows: For executable files with the .exe extension,"] #[doc = " it can be omitted when specifying the program for this Command."] #[doc = " However, if the file has a different extension,"] #[doc = " a filename including the extension needs to be provided,"] #[doc = " otherwise the file won't be found."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"sh\")"] #[doc = "     .spawn()"] #[doc = "     .expect(\"sh command failed to start\");"] #[doc = " ```"] #[doc = ""] #[doc = " # Caveats"] #[doc = ""] #[doc = " [`Command::new`] is only intended to accept the path of the program. If you pass a program"] #[doc = " path along with arguments like `Command::new(\"ls -l\").spawn()`, it will try to search for"] #[doc = " `ls -l` literally. The arguments need to be passed separately, such as via [`arg`] or"] #[doc = " [`args`]."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .arg(\"-l\") // arg passed separately"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`arg`]: Self::arg"] #[doc = " [`args`]: Self::args"] #[stable (feature = "process" , since = "1.0.0")] pub fn new < S : AsRef < OsStr > > (program : S) -> Command { Command { inner : imp :: Command :: new (program . as_ref ()) } } #[doc = " Adds an argument to pass to the program."] #[doc = ""] #[doc = " Only one argument can be passed per use. So instead of:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # std::process::Command::new(\"sh\")"] #[doc = " .arg(\"-C /path/to/repo\")"] #[doc = " # ;"] #[doc = " ```"] #[doc = ""] #[doc = " usage would be:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # std::process::Command::new(\"sh\")"] #[doc = " .arg(\"-C\")"] #[doc = " .arg(\"/path/to/repo\")"] #[doc = " # ;"] #[doc = " ```"] #[doc = ""] #[doc = " To pass multiple arguments see [`args`]."] #[doc = ""] #[doc = " [`args`]: Command::args"] #[doc = ""] #[doc = " Note that the argument is not passed through a shell, but given"] #[doc = " literally to the program. This means that shell syntax like quotes,"] #[doc = " escaped characters, word splitting, glob patterns, variable substitution,"] #[doc = " etc. have no effect."] #[doc = ""] #[doc = " <div class=\"warning\">"] #[doc = ""] #[doc = " On Windows, use caution with untrusted inputs. Most applications use the"] #[doc = " standard convention for decoding arguments passed to them. These are safe to"] #[doc = " use with `arg`. However, some applications such as `cmd.exe` and `.bat` files"] #[doc = " use a non-standard way of decoding arguments. They are therefore vulnerable"] #[doc = " to malicious input."] #[doc = ""] #[doc = " In the case of `cmd.exe` this is especially important because a malicious"] #[doc = " argument can potentially run arbitrary shell commands."] #[doc = ""] #[doc = " See [Windows argument splitting][windows-args] for more details"] #[doc = " or [`raw_arg`] for manually implementing non-standard argument encoding."] #[doc = ""] #[doc = " [`raw_arg`]: crate::os::windows::process::CommandExt::raw_arg"] #[doc = " [windows-args]: crate::process#windows-argument-splitting"] #[doc = ""] #[doc = " </div>"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .arg(\"-l\")"] #[doc = "     .arg(\"-a\")"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn arg < S : AsRef < OsStr > > (& mut self , arg : S) -> & mut Command { self . inner . arg (arg . as_ref ()) ; self } #[doc = " Adds multiple arguments to pass to the program."] #[doc = ""] #[doc = " To pass a single argument see [`arg`]."] #[doc = ""] #[doc = " [`arg`]: Command::arg"] #[doc = ""] #[doc = " Note that the arguments are not passed through a shell, but given"] #[doc = " literally to the program. This means that shell syntax like quotes,"] #[doc = " escaped characters, word splitting, glob patterns, variable substitution, etc."] #[doc = " have no effect."] #[doc = ""] #[doc = " <div class=\"warning\">"] #[doc = ""] #[doc = " On Windows, use caution with untrusted inputs. Most applications use the"] #[doc = " standard convention for decoding arguments passed to them. These are safe to"] #[doc = " use with `arg`. However, some applications such as `cmd.exe` and `.bat` files"] #[doc = " use a non-standard way of decoding arguments. They are therefore vulnerable"] #[doc = " to malicious input."] #[doc = ""] #[doc = " In the case of `cmd.exe` this is especially important because a malicious"] #[doc = " argument can potentially run arbitrary shell commands."] #[doc = ""] #[doc = " See [Windows argument splitting][windows-args] for more details"] #[doc = " or [`raw_arg`] for manually implementing non-standard argument encoding."] #[doc = ""] #[doc = " [`raw_arg`]: crate::os::windows::process::CommandExt::raw_arg"] #[doc = " [windows-args]: crate::process#windows-argument-splitting"] #[doc = ""] #[doc = " </div>"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .args([\"-l\", \"-a\"])"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn args < I , S > (& mut self , args : I) -> & mut Command where I : IntoIterator < Item = S > , S : AsRef < OsStr > , { for arg in args { self . arg (arg . as_ref ()) ; } self } #[doc = " Inserts or updates an explicit environment variable mapping."] #[doc = ""] #[doc = " This method allows you to add an environment variable mapping to the spawned process or"] #[doc = " overwrite a previously set value. You can use [`Command::envs`] to set multiple environment"] #[doc = " variables simultaneously."] #[doc = ""] #[doc = " Child processes will inherit environment variables from their parent process by default."] #[doc = " Environment variables explicitly set using [`Command::env`] take precedence over inherited"] #[doc = " variables. You can disable environment variable inheritance entirely using"] #[doc = " [`Command::env_clear`] or for a single key using [`Command::env_remove`]."] #[doc = ""] #[doc = " Note that environment variable names are case-insensitive (but"] #[doc = " case-preserving) on Windows and case-sensitive on all other platforms."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .env(\"PATH\", \"/bin\")"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn env < K , V > (& mut self , key : K , val : V) -> & mut Command where K : AsRef < OsStr > , V : AsRef < OsStr > , { self . inner . env_mut () . set (key . as_ref () , val . as_ref ()) ; self } #[doc = " Inserts or updates multiple explicit environment variable mappings."] #[doc = ""] #[doc = " This method allows you to add multiple environment variable mappings to the spawned process"] #[doc = " or overwrite previously set values. You can use [`Command::env`] to set a single environment"] #[doc = " variable."] #[doc = ""] #[doc = " Child processes will inherit environment variables from their parent process by default."] #[doc = " Environment variables explicitly set using [`Command::envs`] take precedence over inherited"] #[doc = " variables. You can disable environment variable inheritance entirely using"] #[doc = " [`Command::env_clear`] or for a single key using [`Command::env_remove`]."] #[doc = ""] #[doc = " Note that environment variable names are case-insensitive (but case-preserving) on Windows"] #[doc = " and case-sensitive on all other platforms."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = " use std::env;"] #[doc = " use std::collections::HashMap;"] #[doc = ""] #[doc = " let filtered_env : HashMap<String, String> ="] #[doc = "     env::vars().filter(|&(ref k, _)|"] #[doc = "         k == \"TERM\" || k == \"TZ\" || k == \"LANG\" || k == \"PATH\""] #[doc = "     ).collect();"] #[doc = ""] #[doc = " Command::new(\"printenv\")"] #[doc = "     .stdin(Stdio::null())"] #[doc = "     .stdout(Stdio::inherit())"] #[doc = "     .env_clear()"] #[doc = "     .envs(&filtered_env)"] #[doc = "     .spawn()"] #[doc = "     .expect(\"printenv failed to start\");"] #[doc = " ```"] #[stable (feature = "command_envs" , since = "1.19.0")] pub fn envs < I , K , V > (& mut self , vars : I) -> & mut Command where I : IntoIterator < Item = (K , V) > , K : AsRef < OsStr > , V : AsRef < OsStr > , { for (ref key , ref val) in vars { self . inner . env_mut () . set (key . as_ref () , val . as_ref ()) ; } self } #[doc = " Removes an explicitly set environment variable and prevents inheriting it from a parent"] #[doc = " process."] #[doc = ""] #[doc = " This method will remove the explicit value of an environment variable set via"] #[doc = " [`Command::env`] or [`Command::envs`]. In addition, it will prevent the spawned child"] #[doc = " process from inheriting that environment variable from its parent process."] #[doc = ""] #[doc = " After calling [`Command::env_remove`], the value associated with its key from"] #[doc = " [`Command::get_envs`] will be [`None`]."] #[doc = ""] #[doc = " To clear all explicitly set environment variables and disable all environment variable"] #[doc = " inheritance, you can use [`Command::env_clear`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Prevent any inherited `GIT_DIR` variable from changing the target of the `git` command,"] #[doc = " while allowing all other variables, like `GIT_AUTHOR_NAME`."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"git\")"] #[doc = "     .arg(\"commit\")"] #[doc = "     .env_remove(\"GIT_DIR\")"] #[doc = "     .spawn()?;"] #[doc = " # std::io::Result::Ok(())"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn env_remove < K : AsRef < OsStr > > (& mut self , key : K) -> & mut Command { self . inner . env_mut () . remove (key . as_ref ()) ; self } #[doc = " Clears all explicitly set environment variables and prevents inheriting any parent process"] #[doc = " environment variables."] #[doc = ""] #[doc = " This method will remove all explicitly added environment variables set via [`Command::env`]"] #[doc = " or [`Command::envs`]. In addition, it will prevent the spawned child process from inheriting"] #[doc = " any environment variable from its parent process."] #[doc = ""] #[doc = " After calling [`Command::env_clear`], the iterator from [`Command::get_envs`] will be"] #[doc = " empty."] #[doc = ""] #[doc = " You can use [`Command::env_remove`] to clear a single mapping."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " The behavior of `sort` is affected by `LANG` and `LC_*` environment variables."] #[doc = " Clearing the environment makes `sort`'s behavior independent of the parent processes' language."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"sort\")"] #[doc = "     .arg(\"file.txt\")"] #[doc = "     .env_clear()"] #[doc = "     .spawn()?;"] #[doc = " # std::io::Result::Ok(())"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn env_clear (& mut self) -> & mut Command { self . inner . env_mut () . clear () ; self } #[doc = " Sets the working directory for the child process."] #[doc = ""] #[doc = " # Platform-specific behavior"] #[doc = ""] #[doc = " If the program path is relative (e.g., `\"./script.sh\"`), it's ambiguous"] #[doc = " whether it should be interpreted relative to the parent's working"] #[doc = " directory or relative to `current_dir`. The behavior in this case is"] #[doc = " platform specific and unstable, and it's recommended to use"] #[doc = " [`canonicalize`] to get an absolute program path instead."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .current_dir(\"/bin\")"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`canonicalize`]: crate::fs::canonicalize"] #[stable (feature = "process" , since = "1.0.0")] pub fn current_dir < P : AsRef < Path > > (& mut self , dir : P) -> & mut Command { self . inner . cwd (dir . as_ref () . as_ref ()) ; self } #[doc = " Configuration for the child process's standard input (stdin) handle."] #[doc = ""] #[doc = " Defaults to [`inherit`] when used with [`spawn`] or [`status`], and"] #[doc = " defaults to [`piped`] when used with [`output`]."] #[doc = ""] #[doc = " [`inherit`]: Stdio::inherit"] #[doc = " [`piped`]: Stdio::piped"] #[doc = " [`spawn`]: Self::spawn"] #[doc = " [`status`]: Self::status"] #[doc = " [`output`]: Self::output"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .stdin(Stdio::null())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn stdin < T : Into < Stdio > > (& mut self , cfg : T) -> & mut Command { self . inner . stdin (cfg . into () . 0) ; self } #[doc = " Configuration for the child process's standard output (stdout) handle."] #[doc = ""] #[doc = " Defaults to [`inherit`] when used with [`spawn`] or [`status`], and"] #[doc = " defaults to [`piped`] when used with [`output`]."] #[doc = ""] #[doc = " [`inherit`]: Stdio::inherit"] #[doc = " [`piped`]: Stdio::piped"] #[doc = " [`spawn`]: Self::spawn"] #[doc = " [`status`]: Self::status"] #[doc = " [`output`]: Self::output"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .stdout(Stdio::null())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn stdout < T : Into < Stdio > > (& mut self , cfg : T) -> & mut Command { self . inner . stdout (cfg . into () . 0) ; self } #[doc = " Configuration for the child process's standard error (stderr) handle."] #[doc = ""] #[doc = " Defaults to [`inherit`] when used with [`spawn`] or [`status`], and"] #[doc = " defaults to [`piped`] when used with [`output`]."] #[doc = ""] #[doc = " [`inherit`]: Stdio::inherit"] #[doc = " [`piped`]: Stdio::piped"] #[doc = " [`spawn`]: Self::spawn"] #[doc = " [`status`]: Self::status"] #[doc = " [`output`]: Self::output"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .stderr(Stdio::null())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn stderr < T : Into < Stdio > > (& mut self , cfg : T) -> & mut Command { self . inner . stderr (cfg . into () . 0) ; self } #[doc = " Executes the command as a child process, returning a handle to it."] #[doc = ""] #[doc = " By default, stdin, stdout and stderr are inherited from the parent."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " Command::new(\"ls\")"] #[doc = "     .spawn()"] #[doc = "     .expect(\"ls command failed to start\");"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn spawn (& mut self) -> io :: Result < Child > { self . inner . spawn (imp :: Stdio :: Inherit , true) . map (Child :: from_inner) } #[doc = " Executes the command as a child process, waiting for it to finish and"] #[doc = " collecting all of its output."] #[doc = ""] #[doc = " By default, stdout and stderr are captured (and used to provide the"] #[doc = " resulting output). Stdin is not inherited from the parent and any"] #[doc = " attempt by the child process to read from the stdin stream will result"] #[doc = " in the stream immediately closing."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```should_panic"] #[doc = " use std::process::Command;"] #[doc = " use std::io::{self, Write};"] #[doc = " let output = Command::new(\"/bin/cat\")"] #[doc = "     .arg(\"file.txt\")"] #[doc = "     .output()?;"] #[doc = ""] #[doc = " println!(\"status: {}\", output.status);"] #[doc = " io::stdout().write_all(&output.stdout)?;"] #[doc = " io::stderr().write_all(&output.stderr)?;"] #[doc = ""] #[doc = " assert!(output.status.success());"] #[doc = " # io::Result::Ok(())"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn output (& mut self) -> io :: Result < Output > { let (status , stdout , stderr) = imp :: output (& mut self . inner) ? ; Ok (Output { status : ExitStatus (status) , stdout , stderr }) } #[doc = " Executes a command as a child process, waiting for it to finish and"] #[doc = " collecting its status."] #[doc = ""] #[doc = " By default, stdin, stdout and stderr are inherited from the parent."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```should_panic"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let status = Command::new(\"/bin/cat\")"] #[doc = "     .arg(\"file.txt\")"] #[doc = "     .status()"] #[doc = "     .expect(\"failed to execute process\");"] #[doc = ""] #[doc = " println!(\"process finished with: {status}\");"] #[doc = ""] #[doc = " assert!(status.success());"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn status (& mut self) -> io :: Result < ExitStatus > { self . inner . spawn (imp :: Stdio :: Inherit , true) . map (Child :: from_inner) . and_then (| mut p | p . wait ()) } #[doc = " Returns the path to the program that was given to [`Command::new`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let cmd = Command::new(\"echo\");"] #[doc = " assert_eq!(cmd.get_program(), \"echo\");"] #[doc = " ```"] #[must_use] #[stable (feature = "command_access" , since = "1.57.0")] pub fn get_program (& self) -> & OsStr { self . inner . get_program () } #[doc = " Returns an iterator of the arguments that will be passed to the program."] #[doc = ""] #[doc = " This does not include the path to the program as the first argument;"] #[doc = " it only includes the arguments specified with [`Command::arg`] and"] #[doc = " [`Command::args`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::ffi::OsStr;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut cmd = Command::new(\"echo\");"] #[doc = " cmd.arg(\"first\").arg(\"second\");"] #[doc = " let args: Vec<&OsStr> = cmd.get_args().collect();"] #[doc = " assert_eq!(args, &[\"first\", \"second\"]);"] #[doc = " ```"] #[stable (feature = "command_access" , since = "1.57.0")] pub fn get_args (& self) -> CommandArgs < '_ > { CommandArgs { inner : self . inner . get_args () } } #[doc = " Returns an iterator of the environment variables explicitly set for the child process."] #[doc = ""] #[doc = " Environment variables explicitly set using [`Command::env`], [`Command::envs`], and"] #[doc = " [`Command::env_remove`] can be retrieved with this method."] #[doc = ""] #[doc = " Note that this output does not include environment variables inherited from the parent"] #[doc = " process."] #[doc = ""] #[doc = " Each element is a tuple key/value pair `(&OsStr, Option<&OsStr>)`. A [`None`] value"] #[doc = " indicates its key was explicitly removed via [`Command::env_remove`]. The associated key for"] #[doc = " the [`None`] value will no longer inherit from its parent process."] #[doc = ""] #[doc = " An empty iterator can indicate that no explicit mappings were added or that"] #[doc = " [`Command::env_clear`] was called. After calling [`Command::env_clear`], the child process"] #[doc = " will not inherit any environment variables from its parent process."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::ffi::OsStr;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut cmd = Command::new(\"ls\");"] #[doc = " cmd.env(\"TERM\", \"dumb\").env_remove(\"TZ\");"] #[doc = " let envs: Vec<(&OsStr, Option<&OsStr>)> = cmd.get_envs().collect();"] #[doc = " assert_eq!(envs, &["] #[doc = "     (OsStr::new(\"TERM\"), Some(OsStr::new(\"dumb\"))),"] #[doc = "     (OsStr::new(\"TZ\"), None)"] #[doc = " ]);"] #[doc = " ```"] #[stable (feature = "command_access" , since = "1.57.0")] pub fn get_envs (& self) -> CommandEnvs < '_ > { CommandEnvs { iter : self . inner . get_envs () } } #[doc = " Returns the working directory for the child process."] #[doc = ""] #[doc = " This returns [`None`] if the working directory will not be changed."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::path::Path;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut cmd = Command::new(\"ls\");"] #[doc = " assert_eq!(cmd.get_current_dir(), None);"] #[doc = " cmd.current_dir(\"/bin\");"] #[doc = " assert_eq!(cmd.get_current_dir(), Some(Path::new(\"/bin\")));"] #[doc = " ```"] #[must_use] #[stable (feature = "command_access" , since = "1.57.0")] pub fn get_current_dir (& self) -> Option < & Path > { self . inner . get_current_dir () } } #[stable (feature = "rust1" , since = "1.0.0")] impl fmt :: Debug for Command { #[doc = " Format the program and arguments of a Command for display. Any"] #[doc = " non-utf8 data is lossily converted using the utf8 replacement"] #[doc = " character."] #[doc = ""] #[doc = " The default format approximates a shell invocation of the program along with its"] #[doc = " arguments. It does not include most of the other command properties. The output is not guaranteed to work"] #[doc = " (e.g. due to lack of shell-escaping or differences in path resolution)."] #[doc = " On some platforms you can use [the alternate syntax] to show more fields."] #[doc = ""] #[doc = " Note that the debug implementation is platform-specific."] #[doc = ""] #[doc = " [the alternate syntax]: fmt#sign0"] fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . inner . fmt (f) } } impl AsInner < imp :: Command > for Command { #[inline] fn as_inner (& self) -> & imp :: Command { & self . inner } } impl AsInnerMut < imp :: Command > for Command { #[inline] fn as_inner_mut (& mut self) -> & mut imp :: Command { & mut self . inner } } #[doc = " An iterator over the command arguments."] #[doc = ""] #[doc = " This struct is created by [`Command::get_args`]. See its documentation for"] #[doc = " more."] #[must_use = "iterators are lazy and do nothing unless consumed"] #[stable (feature = "command_access" , since = "1.57.0")] #[derive (Debug)] pub struct CommandArgs < 'a > { inner : imp :: CommandArgs < 'a > , } #[stable (feature = "command_access" , since = "1.57.0")] impl < 'a > Iterator for CommandArgs < 'a > { type Item = & 'a OsStr ; fn next (& mut self) -> Option < & 'a OsStr > { self . inner . next () } fn size_hint (& self) -> (usize , Option < usize >) { self . inner . size_hint () } } #[stable (feature = "command_access" , since = "1.57.0")] impl < 'a > ExactSizeIterator for CommandArgs < 'a > { fn len (& self) -> usize { self . inner . len () } fn is_empty (& self) -> bool { self . inner . is_empty () } } #[doc = " An iterator over the command environment variables."] #[doc = ""] #[doc = " This struct is created by"] #[doc = " [`Command::get_envs`][crate::process::Command::get_envs]. See its"] #[doc = " documentation for more."] #[must_use = "iterators are lazy and do nothing unless consumed"] #[stable (feature = "command_access" , since = "1.57.0")] pub struct CommandEnvs < 'a > { iter : imp :: CommandEnvs < 'a > , } #[stable (feature = "command_access" , since = "1.57.0")] impl < 'a > Iterator for CommandEnvs < 'a > { type Item = (& 'a OsStr , Option < & 'a OsStr >) ; fn next (& mut self) -> Option < Self :: Item > { self . iter . next () } fn size_hint (& self) -> (usize , Option < usize >) { self . iter . size_hint () } } #[stable (feature = "command_access" , since = "1.57.0")] impl < 'a > ExactSizeIterator for CommandEnvs < 'a > { fn len (& self) -> usize { self . iter . len () } fn is_empty (& self) -> bool { self . iter . is_empty () } } #[stable (feature = "command_access" , since = "1.57.0")] impl < 'a > fmt :: Debug for CommandEnvs < 'a > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . iter . fmt (f) } } #[doc = " The output of a finished process."] #[doc = ""] #[doc = " This is returned in a Result by either the [`output`] method of a"] #[doc = " [`Command`], or the [`wait_with_output`] method of a [`Child`]"] #[doc = " process."] #[doc = ""] #[doc = " [`output`]: Command::output"] #[doc = " [`wait_with_output`]: Child::wait_with_output"] #[derive (PartialEq , Eq , Clone)] #[stable (feature = "process" , since = "1.0.0")] pub struct Output { #[doc = " The status (exit code) of the process."] #[stable (feature = "process" , since = "1.0.0")] pub status : ExitStatus , #[doc = " The data that the process wrote to stdout."] #[stable (feature = "process" , since = "1.0.0")] pub stdout : Vec < u8 > , #[doc = " The data that the process wrote to stderr."] #[stable (feature = "process" , since = "1.0.0")] pub stderr : Vec < u8 > , } impl Output { #[doc = " Returns an error if a nonzero exit status was received."] #[doc = ""] #[doc = " If the [`Command`] exited successfully,"] #[doc = " `self` is returned."] #[doc = ""] #[doc = " This is equivalent to calling [`exit_ok`](ExitStatus::exit_ok)"] #[doc = " on [`Output.status`](Output::status)."] #[doc = ""] #[doc = " Note that this will throw away the [`Output::stderr`] field in the error case."] #[doc = " If the child process outputs useful informantion to stderr, you can:"] #[doc = " * Use `cmd.stderr(Stdio::inherit())` to forward the"] #[doc = "   stderr child process to the parent's stderr,"] #[doc = "   usually printing it to console where the user can see it."] #[doc = "   This is usually correct for command-line applications."] #[doc = " * Capture `stderr` using a custom error type."] #[doc = "   This is usually correct for libraries."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(exit_status_error)]"] #[doc = " # #[cfg(all(unix, not(target_os = \"android\")))] {"] #[doc = " use std::process::Command;"] #[doc = " assert!(Command::new(\"false\").output().unwrap().exit_ok().is_err());"] #[doc = " # }"] #[doc = " ```"] #[unstable (feature = "exit_status_error" , issue = "84908")] pub fn exit_ok (self) -> Result < Self , ExitStatusError > { self . status . exit_ok () ? ; Ok (self) } } #[stable (feature = "process_output_debug" , since = "1.7.0")] impl fmt :: Debug for Output { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { let stdout_utf8 = str :: from_utf8 (& self . stdout) ; let stdout_debug : & dyn fmt :: Debug = match stdout_utf8 { Ok (ref s) => s , Err (_) => & self . stdout , } ; let stderr_utf8 = str :: from_utf8 (& self . stderr) ; let stderr_debug : & dyn fmt :: Debug = match stderr_utf8 { Ok (ref s) => s , Err (_) => & self . stderr , } ; fmt . debug_struct ("Output") . field ("status" , & self . status) . field ("stdout" , stdout_debug) . field ("stderr" , stderr_debug) . finish () } } #[doc = " Describes what to do with a standard I/O stream for a child process when"] #[doc = " passed to the [`stdin`], [`stdout`], and [`stderr`] methods of [`Command`]."] #[doc = ""] #[doc = " [`stdin`]: Command::stdin"] #[doc = " [`stdout`]: Command::stdout"] #[doc = " [`stderr`]: Command::stderr"] #[stable (feature = "process" , since = "1.0.0")] pub struct Stdio (imp :: Stdio) ; impl Stdio { #[doc = " A new pipe should be arranged to connect the parent and child processes."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " With stdout:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let output = Command::new(\"echo\")"] #[doc = "     .arg(\"Hello, world!\")"] #[doc = "     .stdout(Stdio::piped())"] #[doc = "     .output()"] #[doc = "     .expect(\"Failed to execute command\");"] #[doc = ""] #[doc = " assert_eq!(String::from_utf8_lossy(&output.stdout), \"Hello, world!\\n\");"] #[doc = " // Nothing echoed to console"] #[doc = " ```"] #[doc = ""] #[doc = " With stdin:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::Write;"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let mut child = Command::new(\"rev\")"] #[doc = "     .stdin(Stdio::piped())"] #[doc = "     .stdout(Stdio::piped())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"Failed to spawn child process\");"] #[doc = ""] #[doc = " let mut stdin = child.stdin.take().expect(\"Failed to open stdin\");"] #[doc = " std::thread::spawn(move || {"] #[doc = "     stdin.write_all(\"Hello, world!\".as_bytes()).expect(\"Failed to write to stdin\");"] #[doc = " });"] #[doc = ""] #[doc = " let output = child.wait_with_output().expect(\"Failed to read stdout\");"] #[doc = " assert_eq!(String::from_utf8_lossy(&output.stdout), \"!dlrow ,olleH\");"] #[doc = " ```"] #[doc = ""] #[doc = " Writing more than a pipe buffer's worth of input to stdin without also reading"] #[doc = " stdout and stderr at the same time may cause a deadlock."] #[doc = " This is an issue when running any program that doesn't guarantee that it reads"] #[doc = " its entire stdin before writing more than a pipe buffer's worth of output."] #[doc = " The size of a pipe buffer varies on different targets."] #[doc = ""] #[must_use] #[stable (feature = "process" , since = "1.0.0")] pub fn piped () -> Stdio { Stdio (imp :: Stdio :: MakePipe) } #[doc = " The child inherits from the corresponding parent descriptor."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " With stdout:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let output = Command::new(\"echo\")"] #[doc = "     .arg(\"Hello, world!\")"] #[doc = "     .stdout(Stdio::inherit())"] #[doc = "     .output()"] #[doc = "     .expect(\"Failed to execute command\");"] #[doc = ""] #[doc = " assert_eq!(String::from_utf8_lossy(&output.stdout), \"\");"] #[doc = " // \"Hello, world!\" echoed to console"] #[doc = " ```"] #[doc = ""] #[doc = " With stdin:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = " use std::io::{self, Write};"] #[doc = ""] #[doc = " let output = Command::new(\"rev\")"] #[doc = "     .stdin(Stdio::inherit())"] #[doc = "     .stdout(Stdio::piped())"] #[doc = "     .output()?;"] #[doc = ""] #[doc = " print!(\"You piped in the reverse of: \");"] #[doc = " io::stdout().write_all(&output.stdout)?;"] #[doc = " # io::Result::Ok(())"] #[doc = " ```"] #[must_use] #[stable (feature = "process" , since = "1.0.0")] pub fn inherit () -> Stdio { Stdio (imp :: Stdio :: Inherit) } #[doc = " This stream will be ignored. This is the equivalent of attaching the"] #[doc = " stream to `/dev/null`."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " With stdout:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let output = Command::new(\"echo\")"] #[doc = "     .arg(\"Hello, world!\")"] #[doc = "     .stdout(Stdio::null())"] #[doc = "     .output()"] #[doc = "     .expect(\"Failed to execute command\");"] #[doc = ""] #[doc = " assert_eq!(String::from_utf8_lossy(&output.stdout), \"\");"] #[doc = " // Nothing echoed to console"] #[doc = " ```"] #[doc = ""] #[doc = " With stdin:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let output = Command::new(\"rev\")"] #[doc = "     .stdin(Stdio::null())"] #[doc = "     .stdout(Stdio::piped())"] #[doc = "     .output()"] #[doc = "     .expect(\"Failed to execute command\");"] #[doc = ""] #[doc = " assert_eq!(String::from_utf8_lossy(&output.stdout), \"\");"] #[doc = " // Ignores any piped-in input"] #[doc = " ```"] #[must_use] #[stable (feature = "process" , since = "1.0.0")] pub fn null () -> Stdio { Stdio (imp :: Stdio :: Null) } #[doc = " Returns `true` if this requires [`Command`] to create a new pipe."] #[doc = ""] #[doc = " # Example"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(stdio_makes_pipe)]"] #[doc = " use std::process::Stdio;"] #[doc = ""] #[doc = " let io = Stdio::piped();"] #[doc = " assert_eq!(io.makes_pipe(), true);"] #[doc = " ```"] #[unstable (feature = "stdio_makes_pipe" , issue = "98288")] pub fn makes_pipe (& self) -> bool { matches ! (self . 0 , imp :: Stdio :: MakePipe) } } impl FromInner < imp :: Stdio > for Stdio { fn from_inner (inner : imp :: Stdio) -> Stdio { Stdio (inner) } } #[stable (feature = "std_debug" , since = "1.16.0")] impl fmt :: Debug for Stdio { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("Stdio") . finish_non_exhaustive () } } #[stable (feature = "stdio_from" , since = "1.20.0")] impl From < ChildStdin > for Stdio { #[doc = " Converts a [`ChildStdin`] into a [`Stdio`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " `ChildStdin` will be converted to `Stdio` using `Stdio::from` under the hood."] #[doc = ""] #[doc = " ```rust,no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let reverse = Command::new(\"rev\")"] #[doc = "     .stdin(Stdio::piped())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"failed reverse command\");"] #[doc = ""] #[doc = " let _echo = Command::new(\"echo\")"] #[doc = "     .arg(\"Hello, world!\")"] #[doc = "     .stdout(reverse.stdin.unwrap()) // Converted into a Stdio here"] #[doc = "     .output()"] #[doc = "     .expect(\"failed echo command\");"] #[doc = ""] #[doc = " // \"!dlrow ,olleH\" echoed to console"] #[doc = " ```"] fn from (child : ChildStdin) -> Stdio { Stdio :: from_inner (child . into_inner () . into ()) } } #[stable (feature = "stdio_from" , since = "1.20.0")] impl From < ChildStdout > for Stdio { #[doc = " Converts a [`ChildStdout`] into a [`Stdio`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " `ChildStdout` will be converted to `Stdio` using `Stdio::from` under the hood."] #[doc = ""] #[doc = " ```rust,no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let hello = Command::new(\"echo\")"] #[doc = "     .arg(\"Hello, world!\")"] #[doc = "     .stdout(Stdio::piped())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"failed echo command\");"] #[doc = ""] #[doc = " let reverse = Command::new(\"rev\")"] #[doc = "     .stdin(hello.stdout.unwrap())  // Converted into a Stdio here"] #[doc = "     .output()"] #[doc = "     .expect(\"failed reverse command\");"] #[doc = ""] #[doc = " assert_eq!(reverse.stdout, b\"!dlrow ,olleH\\n\");"] #[doc = " ```"] fn from (child : ChildStdout) -> Stdio { Stdio :: from_inner (child . into_inner () . into ()) } } #[stable (feature = "stdio_from" , since = "1.20.0")] impl From < ChildStderr > for Stdio { #[doc = " Converts a [`ChildStderr`] into a [`Stdio`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust,no_run"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let reverse = Command::new(\"rev\")"] #[doc = "     .arg(\"non_existing_file.txt\")"] #[doc = "     .stderr(Stdio::piped())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"failed reverse command\");"] #[doc = ""] #[doc = " let cat = Command::new(\"cat\")"] #[doc = "     .arg(\"-\")"] #[doc = "     .stdin(reverse.stderr.unwrap()) // Converted into a Stdio here"] #[doc = "     .output()"] #[doc = "     .expect(\"failed echo command\");"] #[doc = ""] #[doc = " assert_eq!("] #[doc = "     String::from_utf8_lossy(&cat.stdout),"] #[doc = "     \"rev: cannot open non_existing_file.txt: No such file or directory\\n\""] #[doc = " );"] #[doc = " ```"] fn from (child : ChildStderr) -> Stdio { Stdio :: from_inner (child . into_inner () . into ()) } } #[stable (feature = "stdio_from" , since = "1.20.0")] impl From < fs :: File > for Stdio { #[doc = " Converts a [`File`](fs::File) into a [`Stdio`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " `File` will be converted to `Stdio` using `Stdio::from` under the hood."] #[doc = ""] #[doc = " ```rust,no_run"] #[doc = " use std::fs::File;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " // With the `foo.txt` file containing \"Hello, world!\""] #[doc = " let file = File::open(\"foo.txt\")?;"] #[doc = ""] #[doc = " let reverse = Command::new(\"rev\")"] #[doc = "     .stdin(file)  // Implicit File conversion into a Stdio"] #[doc = "     .output()?;"] #[doc = ""] #[doc = " assert_eq!(reverse.stdout, b\"!dlrow ,olleH\");"] #[doc = " # std::io::Result::Ok(())"] #[doc = " ```"] fn from (file : fs :: File) -> Stdio { Stdio :: from_inner (file . into_inner () . into ()) } } #[stable (feature = "stdio_from_stdio" , since = "1.74.0")] impl From < io :: Stdout > for Stdio { #[doc = " Redirect command stdout/stderr to our stdout"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(exit_status_error)]"] #[doc = " use std::io;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " # fn test() -> Result<(), Box<dyn std::error::Error>> {"] #[doc = " let output = Command::new(\"whoami\")"] #[doc = "     .stdout(io::stdout())"] #[doc = "     .output()?;"] #[doc = " output.status.exit_ok()?;"] #[doc = " assert!(output.stdout.is_empty());"] #[doc = " # Ok(())"] #[doc = " # }"] #[doc = " #"] #[doc = " # if cfg!(all(unix, not(target_os = \"android\"))) {"] #[doc = " #     test().unwrap();"] #[doc = " # }"] #[doc = " ```"] fn from (inherit : io :: Stdout) -> Stdio { Stdio :: from_inner (inherit . into ()) } } #[stable (feature = "stdio_from_stdio" , since = "1.74.0")] impl From < io :: Stderr > for Stdio { #[doc = " Redirect command stdout/stderr to our stderr"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(exit_status_error)]"] #[doc = " use std::io;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " # fn test() -> Result<(), Box<dyn std::error::Error>> {"] #[doc = " let output = Command::new(\"whoami\")"] #[doc = "     .stdout(io::stderr())"] #[doc = "     .output()?;"] #[doc = " output.status.exit_ok()?;"] #[doc = " assert!(output.stdout.is_empty());"] #[doc = " # Ok(())"] #[doc = " # }"] #[doc = " #"] #[doc = " # if cfg!(all(unix, not(target_os = \"android\"))) {"] #[doc = " #     test().unwrap();"] #[doc = " # }"] #[doc = " ```"] fn from (inherit : io :: Stderr) -> Stdio { Stdio :: from_inner (inherit . into ()) } } #[stable (feature = "anonymous_pipe" , since = "1.87.0")] impl From < io :: PipeWriter > for Stdio { fn from (pipe : io :: PipeWriter) -> Self { Stdio :: from_inner (pipe . into_inner () . into ()) } } #[stable (feature = "anonymous_pipe" , since = "1.87.0")] impl From < io :: PipeReader > for Stdio { fn from (pipe : io :: PipeReader) -> Self { Stdio :: from_inner (pipe . into_inner () . into ()) } } #[doc = " Describes the result of a process after it has terminated."] #[doc = ""] #[doc = " This `struct` is used to represent the exit status or other termination of a child process."] #[doc = " Child processes are created via the [`Command`] struct and their exit"] #[doc = " status is exposed through the [`status`] method, or the [`wait`] method"] #[doc = " of a [`Child`] process."] #[doc = ""] #[doc = " An `ExitStatus` represents every possible disposition of a process.  On Unix this"] #[doc = " is the **wait status**.  It is *not* simply an *exit status* (a value passed to `exit`)."] #[doc = ""] #[doc = " For proper error reporting of failed processes, print the value of `ExitStatus` or"] #[doc = " `ExitStatusError` using their implementations of [`Display`](crate::fmt::Display)."] #[doc = ""] #[doc = " # Differences from `ExitCode`"] #[doc = ""] #[doc = " [`ExitCode`] is intended for terminating the currently running process, via"] #[doc = " the `Termination` trait, in contrast to `ExitStatus`, which represents the"] #[doc = " termination of a child process. These APIs are separate due to platform"] #[doc = " compatibility differences and their expected usage; it is not generally"] #[doc = " possible to exactly reproduce an `ExitStatus` from a child for the current"] #[doc = " process after the fact."] #[doc = ""] #[doc = " [`status`]: Command::status"] #[doc = " [`wait`]: Child::wait"] #[derive (PartialEq , Eq , Clone , Copy , Debug)] #[stable (feature = "process" , since = "1.0.0")] pub struct ExitStatus (imp :: ExitStatus) ; #[doc = " The default value is one which indicates successful completion."] #[stable (feature = "process_exitstatus_default" , since = "1.73.0")] impl Default for ExitStatus { fn default () -> Self { ExitStatus :: from_inner (imp :: ExitStatus :: default ()) } } #[doc = " Allows extension traits within `std`."] #[unstable (feature = "sealed" , issue = "none")] impl crate :: sealed :: Sealed for ExitStatus { } impl ExitStatus { #[doc = " Was termination successful?  Returns a `Result`."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(exit_status_error)]"] #[doc = " # if cfg!(unix) {"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let status = Command::new(\"ls\")"] #[doc = "     .arg(\"/dev/nonexistent\")"] #[doc = "     .status()"] #[doc = "     .expect(\"ls could not be executed\");"] #[doc = ""] #[doc = " println!(\"ls: {status}\");"] #[doc = " status.exit_ok().expect_err(\"/dev/nonexistent could be listed!\");"] #[doc = " # } // cfg!(unix)"] #[doc = " ```"] #[unstable (feature = "exit_status_error" , issue = "84908")] pub fn exit_ok (& self) -> Result < () , ExitStatusError > { self . 0 . exit_ok () . map_err (ExitStatusError) } #[doc = " Was termination successful? Signal termination is not considered a"] #[doc = " success, and success is defined as a zero exit status."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```rust,no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let status = Command::new(\"mkdir\")"] #[doc = "     .arg(\"projects\")"] #[doc = "     .status()"] #[doc = "     .expect(\"failed to execute mkdir\");"] #[doc = ""] #[doc = " if status.success() {"] #[doc = "     println!(\"'projects/' directory created\");"] #[doc = " } else {"] #[doc = "     println!(\"failed to create 'projects/' directory: {status}\");"] #[doc = " }"] #[doc = " ```"] #[must_use] #[stable (feature = "process" , since = "1.0.0")] pub fn success (& self) -> bool { self . 0 . exit_ok () . is_ok () } #[doc = " Returns the exit code of the process, if any."] #[doc = ""] #[doc = " In Unix terms the return value is the **exit status**: the value passed to `exit`, if the"] #[doc = " process finished by calling `exit`.  Note that on Unix the exit status is truncated to 8"] #[doc = " bits, and that values that didn't come from a program's call to `exit` may be invented by the"] #[doc = " runtime system (often, for example, 255, 254, 127 or 126)."] #[doc = ""] #[doc = " On Unix, this will return `None` if the process was terminated by a signal."] #[doc = " [`ExitStatusExt`](crate::os::unix::process::ExitStatusExt) is an"] #[doc = " extension trait for extracting any such signal, and other details, from the `ExitStatus`."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let status = Command::new(\"mkdir\")"] #[doc = "     .arg(\"projects\")"] #[doc = "     .status()"] #[doc = "     .expect(\"failed to execute mkdir\");"] #[doc = ""] #[doc = " match status.code() {"] #[doc = "     Some(code) => println!(\"Exited with status code: {code}\"),"] #[doc = "     None => println!(\"Process terminated by signal\")"] #[doc = " }"] #[doc = " ```"] #[must_use] #[stable (feature = "process" , since = "1.0.0")] pub fn code (& self) -> Option < i32 > { self . 0 . code () } } impl AsInner < imp :: ExitStatus > for ExitStatus { #[inline] fn as_inner (& self) -> & imp :: ExitStatus { & self . 0 } } impl FromInner < imp :: ExitStatus > for ExitStatus { fn from_inner (s : imp :: ExitStatus) -> ExitStatus { ExitStatus (s) } } #[stable (feature = "process" , since = "1.0.0")] impl fmt :: Display for ExitStatus { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . 0 . fmt (f) } } #[doc = " Allows extension traits within `std`."] #[unstable (feature = "sealed" , issue = "none")] impl crate :: sealed :: Sealed for ExitStatusError { } #[doc = " Describes the result of a process after it has failed"] #[doc = ""] #[doc = " Produced by the [`.exit_ok`](ExitStatus::exit_ok) method on [`ExitStatus`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(exit_status_error)]"] #[doc = " # if cfg!(all(unix, not(target_os = \"android\"))) {"] #[doc = " use std::process::{Command, ExitStatusError};"] #[doc = ""] #[doc = " fn run(cmd: &str) -> Result<(), ExitStatusError> {"] #[doc = "     Command::new(cmd).status().unwrap().exit_ok()?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = ""] #[doc = " run(\"true\").unwrap();"] #[doc = " run(\"false\").unwrap_err();"] #[doc = " # } // cfg!(unix)"] #[doc = " ```"] #[derive (PartialEq , Eq , Clone , Copy , Debug)] #[unstable (feature = "exit_status_error" , issue = "84908")] pub struct ExitStatusError (imp :: ExitStatusError) ; #[unstable (feature = "exit_status_error" , issue = "84908")] impl ExitStatusError { #[doc = " Reports the exit code, if applicable, from an `ExitStatusError`."] #[doc = ""] #[doc = " In Unix terms the return value is the **exit status**: the value passed to `exit`, if the"] #[doc = " process finished by calling `exit`.  Note that on Unix the exit status is truncated to 8"] #[doc = " bits, and that values that didn't come from a program's call to `exit` may be invented by the"] #[doc = " runtime system (often, for example, 255, 254, 127 or 126)."] #[doc = ""] #[doc = " On Unix, this will return `None` if the process was terminated by a signal.  If you want to"] #[doc = " handle such situations specially, consider using methods from"] #[doc = " [`ExitStatusExt`](crate::os::unix::process::ExitStatusExt)."] #[doc = ""] #[doc = " If the process finished by calling `exit` with a nonzero value, this will return"] #[doc = " that exit status."] #[doc = ""] #[doc = " If the error was something else, it will return `None`."] #[doc = ""] #[doc = " If the process exited successfully (ie, by calling `exit(0)`), there is no"] #[doc = " `ExitStatusError`.  So the return value from `ExitStatusError::code()` is always nonzero."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(exit_status_error)]"] #[doc = " # #[cfg(all(unix, not(target_os = \"android\")))] {"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let bad = Command::new(\"false\").status().unwrap().exit_ok().unwrap_err();"] #[doc = " assert_eq!(bad.code(), Some(1));"] #[doc = " # } // #[cfg(unix)]"] #[doc = " ```"] #[must_use] pub fn code (& self) -> Option < i32 > { self . code_nonzero () . map (Into :: into) } #[doc = " Reports the exit code, if applicable, from an `ExitStatusError`, as a [`NonZero`]."] #[doc = ""] #[doc = " This is exactly like [`code()`](Self::code), except that it returns a <code>[NonZero]<[i32]></code>."] #[doc = ""] #[doc = " Plain `code`, returning a plain integer, is provided because it is often more convenient."] #[doc = " The returned value from `code()` is indeed also nonzero; use `code_nonzero()` when you want"] #[doc = " a type-level guarantee of nonzeroness."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(exit_status_error)]"] #[doc = ""] #[doc = " # if cfg!(all(unix, not(target_os = \"android\"))) {"] #[doc = " use std::num::NonZero;"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let bad = Command::new(\"false\").status().unwrap().exit_ok().unwrap_err();"] #[doc = " assert_eq!(bad.code_nonzero().unwrap(), NonZero::new(1).unwrap());"] #[doc = " # } // cfg!(unix)"] #[doc = " ```"] #[must_use] pub fn code_nonzero (& self) -> Option < NonZero < i32 > > { self . 0 . code () } #[doc = " Converts an `ExitStatusError` (back) to an `ExitStatus`."] #[must_use] pub fn into_status (& self) -> ExitStatus { ExitStatus (self . 0 . into ()) } } #[unstable (feature = "exit_status_error" , issue = "84908")] impl From < ExitStatusError > for ExitStatus { fn from (error : ExitStatusError) -> Self { Self (error . 0 . into ()) } } #[unstable (feature = "exit_status_error" , issue = "84908")] impl fmt :: Display for ExitStatusError { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (f , "process exited unsuccessfully: {}" , self . into_status ()) } } #[unstable (feature = "exit_status_error" , issue = "84908")] impl crate :: error :: Error for ExitStatusError { } #[doc = " This type represents the status code the current process can return"] #[doc = " to its parent under normal termination."] #[doc = ""] #[doc = " `ExitCode` is intended to be consumed only by the standard library (via"] #[doc = " [`Termination::report()`]). For forwards compatibility with potentially"] #[doc = " unusual targets, this type currently does not provide `Eq`, `Hash`, or"] #[doc = " access to the raw value. This type does provide `PartialEq` for"] #[doc = " comparison, but note that there may potentially be multiple failure"] #[doc = " codes, some of which will _not_ compare equal to `ExitCode::FAILURE`."] #[doc = " The standard library provides the canonical `SUCCESS` and `FAILURE`"] #[doc = " exit codes as well as `From<u8> for ExitCode` for constructing other"] #[doc = " arbitrary exit codes."] #[doc = ""] #[doc = " # Portability"] #[doc = ""] #[doc = " Numeric values used in this type don't have portable meanings, and"] #[doc = " different platforms may mask different amounts of them."] #[doc = ""] #[doc = " For the platform's canonical successful and unsuccessful codes, see"] #[doc = " the [`SUCCESS`] and [`FAILURE`] associated items."] #[doc = ""] #[doc = " [`SUCCESS`]: ExitCode::SUCCESS"] #[doc = " [`FAILURE`]: ExitCode::FAILURE"] #[doc = ""] #[doc = " # Differences from `ExitStatus`"] #[doc = ""] #[doc = " `ExitCode` is intended for terminating the currently running process, via"] #[doc = " the `Termination` trait, in contrast to [`ExitStatus`], which represents the"] #[doc = " termination of a child process. These APIs are separate due to platform"] #[doc = " compatibility differences and their expected usage; it is not generally"] #[doc = " possible to exactly reproduce an `ExitStatus` from a child for the current"] #[doc = " process after the fact."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " `ExitCode` can be returned from the `main` function of a crate, as it implements"] #[doc = " [`Termination`]:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::process::ExitCode;"] #[doc = " # fn check_foo() -> bool { true }"] #[doc = ""] #[doc = " fn main() -> ExitCode {"] #[doc = "     if !check_foo() {"] #[doc = "         return ExitCode::from(42);"] #[doc = "     }"] #[doc = ""] #[doc = "     ExitCode::SUCCESS"] #[doc = " }"] #[doc = " ```"] #[derive (Clone , Copy , Debug , PartialEq)] #[stable (feature = "process_exitcode" , since = "1.61.0")] pub struct ExitCode (imp :: ExitCode) ; #[doc = " Allows extension traits within `std`."] #[unstable (feature = "sealed" , issue = "none")] impl crate :: sealed :: Sealed for ExitCode { } #[stable (feature = "process_exitcode" , since = "1.61.0")] impl ExitCode { #[doc = " The canonical `ExitCode` for successful termination on this platform."] #[doc = ""] #[doc = " Note that a `()`-returning `main` implicitly results in a successful"] #[doc = " termination, so there's no need to return this from `main` unless"] #[doc = " you're also returning other possible codes."] #[stable (feature = "process_exitcode" , since = "1.61.0")] pub const SUCCESS : ExitCode = ExitCode (imp :: ExitCode :: SUCCESS) ; #[doc = " The canonical `ExitCode` for unsuccessful termination on this platform."] #[doc = ""] #[doc = " If you're only returning this and `SUCCESS` from `main`, consider"] #[doc = " instead returning `Err(_)` and `Ok(())` respectively, which will"] #[doc = " return the same codes (but will also `eprintln!` the error)."] #[stable (feature = "process_exitcode" , since = "1.61.0")] pub const FAILURE : ExitCode = ExitCode (imp :: ExitCode :: FAILURE) ; #[doc = " Exit the current process with the given `ExitCode`."] #[doc = ""] #[doc = " Note that this has the same caveats as [`process::exit()`][exit], namely that this function"] #[doc = " terminates the process immediately, so no destructors on the current stack or any other"] #[doc = " thread's stack will be run. Also see those docs for some important notes on interop with C"] #[doc = " code. If a clean shutdown is needed, it is recommended to simply return this ExitCode from"] #[doc = " the `main` function, as demonstrated in the [type documentation](#examples)."] #[doc = ""] #[doc = " # Differences from `process::exit()`"] #[doc = ""] #[doc = " `process::exit()` accepts any `i32` value as the exit code for the process; however, there"] #[doc = " are platforms that only use a subset of that value (see [`process::exit` platform-specific"] #[doc = " behavior][exit#platform-specific-behavior]). `ExitCode` exists because of this; only"] #[doc = " `ExitCode`s that are supported by a majority of our platforms can be created, so those"] #[doc = " problems don't exist (as much) with this method."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(exitcode_exit_method)]"] #[doc = " # use std::process::ExitCode;"] #[doc = " # use std::fmt;"] #[doc = " # enum UhOhError { GenericProblem, Specific, WithCode { exit_code: ExitCode, _x: () } }"] #[doc = " # impl fmt::Display for UhOhError {"] #[doc = " #     fn fmt(&self, _: &mut fmt::Formatter<'_>) -> fmt::Result { unimplemented!() }"] #[doc = " # }"] #[doc = " // there's no way to gracefully recover from an UhOhError, so we just"] #[doc = " // print a message and exit"] #[doc = " fn handle_unrecoverable_error(err: UhOhError) -> ! {"] #[doc = "     eprintln!(\"UH OH! {err}\");"] #[doc = "     let code = match err {"] #[doc = "         UhOhError::GenericProblem => ExitCode::FAILURE,"] #[doc = "         UhOhError::Specific => ExitCode::from(3),"] #[doc = "         UhOhError::WithCode { exit_code, .. } => exit_code,"] #[doc = "     };"] #[doc = "     code.exit_process()"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "exitcode_exit_method" , issue = "97100")] pub fn exit_process (self) -> ! { exit (self . to_i32 ()) } } impl ExitCode { #[doc = " Converts an `ExitCode` into an i32"] #[unstable (feature = "process_exitcode_internals" , reason = "exposed only for libstd" , issue = "none")] #[inline] #[doc (hidden)] pub fn to_i32 (self) -> i32 { self . 0 . as_i32 () } } #[doc = " The default value is [`ExitCode::SUCCESS`]"] #[stable (feature = "process_exitcode_default" , since = "1.75.0")] impl Default for ExitCode { fn default () -> Self { ExitCode :: SUCCESS } } #[stable (feature = "process_exitcode" , since = "1.61.0")] impl From < u8 > for ExitCode { #[doc = " Constructs an `ExitCode` from an arbitrary u8 value."] fn from (code : u8) -> Self { ExitCode (imp :: ExitCode :: from (code)) } } impl AsInner < imp :: ExitCode > for ExitCode { #[inline] fn as_inner (& self) -> & imp :: ExitCode { & self . 0 } } impl FromInner < imp :: ExitCode > for ExitCode { fn from_inner (s : imp :: ExitCode) -> ExitCode { ExitCode (s) } } impl Child { #[doc = " Forces the child process to exit. If the child has already exited, `Ok(())`"] #[doc = " is returned."] #[doc = ""] #[doc = " The mapping to [`ErrorKind`]s is not part of the compatibility contract of the function."] #[doc = ""] #[doc = " This is equivalent to sending a SIGKILL on Unix platforms."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut command = Command::new(\"yes\");"] #[doc = " if let Ok(mut child) = command.spawn() {"] #[doc = "     child.kill().expect(\"command couldn't be killed\");"] #[doc = " } else {"] #[doc = "     println!(\"yes command didn't start\");"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [`ErrorKind`]: io::ErrorKind"] #[doc = " [`InvalidInput`]: io::ErrorKind::InvalidInput"] #[stable (feature = "process" , since = "1.0.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "child_kill")] pub fn kill (& mut self) -> io :: Result < () > { self . handle . kill () } #[doc = " Returns the OS-assigned process identifier associated with this child."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut command = Command::new(\"ls\");"] #[doc = " if let Ok(child) = command.spawn() {"] #[doc = "     println!(\"Child's ID is {}\", child.id());"] #[doc = " } else {"] #[doc = "     println!(\"ls command didn't start\");"] #[doc = " }"] #[doc = " ```"] #[must_use] #[stable (feature = "process_id" , since = "1.3.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "child_id")] pub fn id (& self) -> u32 { self . handle . id () } #[doc = " Waits for the child to exit completely, returning the status that it"] #[doc = " exited with. This function will continue to have the same return value"] #[doc = " after it has been called at least once."] #[doc = ""] #[doc = " The stdin handle to the child process, if any, will be closed"] #[doc = " before waiting. This helps avoid deadlock: it ensures that the"] #[doc = " child does not block waiting for input from the parent, while"] #[doc = " the parent waits for the child to exit."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut command = Command::new(\"ls\");"] #[doc = " if let Ok(mut child) = command.spawn() {"] #[doc = "     child.wait().expect(\"command wasn't running\");"] #[doc = "     println!(\"Child has finished its execution!\");"] #[doc = " } else {"] #[doc = "     println!(\"ls command didn't start\");"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "process" , since = "1.0.0")] pub fn wait (& mut self) -> io :: Result < ExitStatus > { drop (self . stdin . take ()) ; self . handle . wait () . map (ExitStatus) } #[doc = " Attempts to collect the exit status of the child if it has already"] #[doc = " exited."] #[doc = ""] #[doc = " This function will not block the calling thread and will only"] #[doc = " check to see if the child process has exited or not. If the child has"] #[doc = " exited then on Unix the process ID is reaped. This function is"] #[doc = " guaranteed to repeatedly return a successful exit status so long as the"] #[doc = " child has already exited."] #[doc = ""] #[doc = " If the child has exited, then `Ok(Some(status))` is returned. If the"] #[doc = " exit status is not available at this time then `Ok(None)` is returned."] #[doc = " If an error occurs, then that error is returned."] #[doc = ""] #[doc = " Note that unlike `wait`, this function will not attempt to drop stdin."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process::Command;"] #[doc = ""] #[doc = " let mut child = Command::new(\"ls\").spawn()?;"] #[doc = ""] #[doc = " match child.try_wait() {"] #[doc = "     Ok(Some(status)) => println!(\"exited with: {status}\"),"] #[doc = "     Ok(None) => {"] #[doc = "         println!(\"status not ready yet, let's really wait\");"] #[doc = "         let res = child.wait();"] #[doc = "         println!(\"result: {res:?}\");"] #[doc = "     }"] #[doc = "     Err(e) => println!(\"error attempting to wait: {e}\"),"] #[doc = " }"] #[doc = " # std::io::Result::Ok(())"] #[doc = " ```"] #[stable (feature = "process_try_wait" , since = "1.18.0")] pub fn try_wait (& mut self) -> io :: Result < Option < ExitStatus > > { Ok (self . handle . try_wait () ? . map (ExitStatus)) } #[doc = " Simultaneously waits for the child to exit and collect all remaining"] #[doc = " output on the stdout/stderr handles, returning an `Output`"] #[doc = " instance."] #[doc = ""] #[doc = " The stdin handle to the child process, if any, will be closed"] #[doc = " before waiting. This helps avoid deadlock: it ensures that the"] #[doc = " child does not block waiting for input from the parent, while"] #[doc = " the parent waits for the child to exit."] #[doc = ""] #[doc = " By default, stdin, stdout and stderr are inherited from the parent."] #[doc = " In order to capture the output into this `Result<Output>` it is"] #[doc = " necessary to create new pipes between parent and child. Use"] #[doc = " `stdout(Stdio::piped())` or `stderr(Stdio::piped())`, respectively."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```should_panic"] #[doc = " use std::process::{Command, Stdio};"] #[doc = ""] #[doc = " let child = Command::new(\"/bin/cat\")"] #[doc = "     .arg(\"file.txt\")"] #[doc = "     .stdout(Stdio::piped())"] #[doc = "     .spawn()"] #[doc = "     .expect(\"failed to execute child\");"] #[doc = ""] #[doc = " let output = child"] #[doc = "     .wait_with_output()"] #[doc = "     .expect(\"failed to wait on child\");"] #[doc = ""] #[doc = " assert!(output.status.success());"] #[doc = " ```"] #[doc = ""] #[stable (feature = "process" , since = "1.0.0")] pub fn wait_with_output (mut self) -> io :: Result < Output > { drop (self . stdin . take ()) ; let (mut stdout , mut stderr) = (Vec :: new () , Vec :: new ()) ; match (self . stdout . take () , self . stderr . take ()) { (None , None) => { } (Some (mut out) , None) => { let res = out . read_to_end (& mut stdout) ; res . unwrap () ; } (None , Some (mut err)) => { let res = err . read_to_end (& mut stderr) ; res . unwrap () ; } (Some (out) , Some (err)) => { let res = read2 (out . inner , & mut stdout , err . inner , & mut stderr) ; res . unwrap () ; } } let status = self . wait () ? ; Ok (Output { status , stdout , stderr }) } } #[doc = " Terminates the current process with the specified exit code."] #[doc = ""] #[doc = " This function will never return and will immediately terminate the current"] #[doc = " process. The exit code is passed through to the underlying OS and will be"] #[doc = " available for consumption by another process."] #[doc = ""] #[doc = " Note that because this function never returns, and that it terminates the"] #[doc = " process, no destructors on the current stack or any other thread's stack"] #[doc = " will be run. If a clean shutdown is needed it is recommended to only call"] #[doc = " this function at a known point where there are no more destructors left"] #[doc = " to run; or, preferably, simply return a type implementing [`Termination`]"] #[doc = " (such as [`ExitCode`] or `Result`) from the `main` function and avoid this"] #[doc = " function altogether:"] #[doc = ""] #[doc = " ```"] #[doc = " # use std::io::Error as MyError;"] #[doc = " fn main() -> Result<(), MyError> {"] #[doc = "     // ..."] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " In its current implementation, this function will execute exit handlers registered with `atexit`"] #[doc = " as well as other platform-specific exit handlers (e.g. `fini` sections of ELF shared objects)."] #[doc = " This means that Rust requires that all exit handlers are safe to execute at any time. In"] #[doc = " particular, if an exit handler cleans up some state that might be concurrently accessed by other"] #[doc = " threads, it is required that the exit handler performs suitable synchronization with those"] #[doc = " threads. (The alternative to this requirement would be to not run exit handlers at all, which is"] #[doc = " considered undesirable. Note that returning from `main` also calls `exit`, so making `exit` an"] #[doc = " unsafe operation is not an option.)"] #[doc = ""] #[doc = " ## Platform-specific behavior"] #[doc = ""] #[doc = " **Unix**: On Unix-like platforms, it is unlikely that all 32 bits of `exit`"] #[doc = " will be visible to a parent process inspecting the exit code. On most"] #[doc = " Unix-like platforms, only the eight least-significant bits are considered."] #[doc = ""] #[doc = " For example, the exit code for this example will be `0` on Linux, but `256`"] #[doc = " on Windows:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process;"] #[doc = ""] #[doc = " process::exit(0x0100);"] #[doc = " ```"] #[doc = ""] #[doc = " ### Safe interop with C code"] #[doc = ""] #[doc = " On Unix, this function is currently implemented using the `exit` C function [`exit`][C-exit]. As"] #[doc = " of C23, the C standard does not permit multiple threads to call `exit` concurrently. Rust"] #[doc = " mitigates this with a lock, but if C code calls `exit`, that can still cause undefined behavior."] #[doc = " Note that returning from `main` is equivalent to calling `exit`."] #[doc = ""] #[doc = " Therefore, it is undefined behavior to have two concurrent threads perform the following"] #[doc = " without synchronization:"] #[doc = " - One thread calls Rust's `exit` function or returns from Rust's `main` function"] #[doc = " - Another thread calls the C function `exit` or `quick_exit`, or returns from C's `main` function"] #[doc = ""] #[doc = " Note that if a binary contains multiple copies of the Rust runtime (e.g., when combining"] #[doc = " multiple `cdylib` or `staticlib`), they each have their own separate lock, so from the"] #[doc = " perspective of code running in one of the Rust runtimes, the \"outside\" Rust code is basically C"] #[doc = " code, and concurrent `exit` again causes undefined behavior."] #[doc = ""] #[doc = " Individual C implementations might provide more guarantees than the standard and permit concurrent"] #[doc = " calls to `exit`; consult the documentation of your C implementation for details."] #[doc = ""] #[doc = " For some of the on-going discussion to make `exit` thread-safe in C, see:"] #[doc = " - [Rust issue #126600](https://github.com/rust-lang/rust/issues/126600)"] #[doc = " - [Austin Group Bugzilla (for POSIX)](https://austingroupbugs.net/view.php?id=1845)"] #[doc = " - [GNU C library Bugzilla](https://sourceware.org/bugzilla/show_bug.cgi?id=31997)"] #[doc = ""] #[doc = " [C-exit]: https://en.cppreference.com/w/c/program/exit"] #[stable (feature = "rust1" , since = "1.0.0")] #[cfg_attr (not (test) , rustc_diagnostic_item = "process_exit")] pub fn exit (code : i32) -> ! { crate :: rt :: cleanup () ; crate :: sys :: os :: exit (code) } #[doc = " Terminates the process in an abnormal fashion."] #[doc = ""] #[doc = " The function will never return and will immediately terminate the current"] #[doc = " process in a platform specific \"abnormal\" manner. As a consequence,"] #[doc = " no destructors on the current stack or any other thread's stack"] #[doc = " will be run, Rust IO buffers (eg, from `BufWriter`) will not be flushed,"] #[doc = " and C stdio buffers will (on most platforms) not be flushed."] #[doc = ""] #[doc = " This is in contrast to the default behavior of [`panic!`] which unwinds"] #[doc = " the current thread's stack and calls all destructors."] #[doc = " When `panic=\"abort\"` is set, either as an argument to `rustc` or in a"] #[doc = " crate's Cargo.toml, [`panic!`] and `abort` are similar. However,"] #[doc = " [`panic!`] will still call the [panic hook] while `abort` will not."] #[doc = ""] #[doc = " If a clean shutdown is needed it is recommended to only call"] #[doc = " this function at a known point where there are no more destructors left"] #[doc = " to run."] #[doc = ""] #[doc = " The process's termination will be similar to that from the C `abort()`"] #[doc = " function.  On Unix, the process will terminate with signal `SIGABRT`, which"] #[doc = " typically means that the shell prints \"Aborted\"."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process;"] #[doc = ""] #[doc = " fn main() {"] #[doc = "     println!(\"aborting\");"] #[doc = ""] #[doc = "     process::abort();"] #[doc = ""] #[doc = "     // execution never gets here"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The `abort` function terminates the process, so the destructor will not"] #[doc = " get run on the example below:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process;"] #[doc = ""] #[doc = " struct HasDrop;"] #[doc = ""] #[doc = " impl Drop for HasDrop {"] #[doc = "     fn drop(&mut self) {"] #[doc = "         println!(\"This will never be printed!\");"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn main() {"] #[doc = "     let _x = HasDrop;"] #[doc = "     process::abort();"] #[doc = "     // the destructor implemented for HasDrop will never get run"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [panic hook]: crate::panic::set_hook"] #[stable (feature = "process_abort" , since = "1.17.0")] #[cold] #[cfg_attr (not (test) , rustc_diagnostic_item = "process_abort")] #[cfg_attr (miri , track_caller)] pub fn abort () -> ! { crate :: sys :: abort_internal () ; } #[doc = " Returns the OS-assigned process identifier associated with this process."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::process;"] #[doc = ""] #[doc = " println!(\"My pid is {}\", process::id());"] #[doc = " ```"] #[must_use] #[stable (feature = "getpid" , since = "1.26.0")] pub fn id () -> u32 { crate :: sys :: os :: getpid () } #[doc = " A trait for implementing arbitrary return types in the `main` function."] #[doc = ""] #[doc = " The C-main function only supports returning integers."] #[doc = " So, every type implementing the `Termination` trait has to be converted"] #[doc = " to an integer."] #[doc = ""] #[doc = " The default implementations are returning `libc::EXIT_SUCCESS` to indicate"] #[doc = " a successful execution. In case of a failure, `libc::EXIT_FAILURE` is returned."] #[doc = ""] #[doc = " Because different runtimes have different specifications on the return value"] #[doc = " of the `main` function, this trait is likely to be available only on"] #[doc = " standard library's runtime for convenience. Other runtimes are not required"] #[doc = " to provide similar functionality."] #[cfg_attr (not (any (test , doctest)) , lang = "termination")] #[stable (feature = "termination_trait_lib" , since = "1.61.0")] #[rustc_on_unimplemented (on (cause = "MainFunctionType" , message = "`main` has invalid return type `{Self}`" , label = "`main` can only return types that implement `{This}`"))] pub trait Termination { #[doc = " Is called to get the representation of the value as status code."] #[doc = " This status code is returned to the operating system."] #[stable (feature = "termination_trait_lib" , since = "1.61.0")] fn report (self) -> ExitCode ; } #[stable (feature = "termination_trait_lib" , since = "1.61.0")] impl Termination for () { #[inline] fn report (self) -> ExitCode { ExitCode :: SUCCESS } } #[stable (feature = "termination_trait_lib" , since = "1.61.0")] impl Termination for ! { fn report (self) -> ExitCode { self } } #[stable (feature = "termination_trait_lib" , since = "1.61.0")] impl Termination for Infallible { fn report (self) -> ExitCode { match self { } } } #[stable (feature = "termination_trait_lib" , since = "1.61.0")] impl Termination for ExitCode { #[inline] fn report (self) -> ExitCode { self } } #[stable (feature = "termination_trait_lib" , since = "1.61.0")] impl < T : Termination , E : fmt :: Debug > Termination for Result < T , E > { fn report (self) -> ExitCode { match self { Ok (val) => val . report () , Err (err) => { io :: attempt_print_to_stderr (format_args_nl ! ("Error: {err:?}")) ; ExitCode :: FAILURE } } } }